21	/// Upper bound on the bytes read for a single OSV record (one zip entry
22	/// or one directory file). OSV advisories are a few KB; this cap only
23	/// exists so a crafted database can't exhaust memory at startup.
24	const MAX_OSV_RECORD_BYTES: u64 = 16 * 1024 * 1024;
25	
26	/// Upper bound on a zip entry's name length. OSV filenames are short
27	/// (`GHSA-….json`); this only rejects crafted names that would otherwise
28	/// force large allocations at startup.
29	const MAX_OSV_NAME_BYTES: usize = 4096;
30	
31	/// Upper bound on a stored advisory id. Real ids are short (`GHSA-…`,
32	/// `CVE-…`); cap so an oversized id from a crafted record can't bloat
33	/// in-memory state or the reason strings it feeds.
34	const MAX_ADVISORY_ID_BYTES: usize = 256;
