    body::{Body, to_bytes},
    http::{Request, StatusCode},
};
use pnpr::{Config, router};
use serde_json::{Value, json};
use std::{
    fs,
    net::{Ipv4Addr, SocketAddr, SocketAddrV4},
    time::Duration,
};
use tempfile::TempDir;
use tower::ServiceExt;

fn write_osv(dir: &std::path::Path) {
    fs::write(
        dir.join("GHSA-foo.json"),
        r#"{
          "id": "GHSA-foo-bar",
          "affected": [{
            "package": { "ecosystem": "npm", "name": "foo" },
            "ranges": [{ "type": "SEMVER", "events": [
              { "introduced": "1.0.0" }, { "fixed": "1.1.0" }
            ]}]
          }]
        }"#,
    )
    .unwrap();
}

fn config_for(upstream: &str, storage: std::path::PathBuf, osv_dir: std::path::PathBuf) -> Config {
    let listen = SocketAddr::V4(SocketAddrV4::new(Ipv4Addr::LOCALHOST, 4873));
    let mut config = Config::proxy(listen, storage);
    config.uplinks.get_mut("npmjs").unwrap().url = upstream.to_string();
    config.public_url = "http://example.test".to_string();
    config.packument_ttl = Duration::from_secs(60);
    config.osv.enabled = true;
    config.osv.path = Some(osv_dir);
    config
}

async fn body_bytes(body: Body) -> Vec<u8> {
    to_bytes(body, usize::MAX).await.unwrap().to_vec()
}

fn packument(upstream: &str) -> Value {
    json!({
        "name": "foo",
        "dist-tags": { "latest": "1.0.0", "safe": "1.1.0" },
        "time": { "1.0.0": "2020-01-01T00:00:00Z", "1.1.0": "2021-01-01T00:00:00Z", "modified": "2021-01-01T00:00:00Z" },
        "versions": {
            "1.0.0": { "name": "foo", "version": "1.0.0", "dist": { "tarball": format!("{upstream}/foo/-/foo-1.0.0.tgz"), "shasum": "aa" } },
            "1.1.0": { "name": "foo", "version": "1.1.0", "dist": { "tarball": format!("{upstream}/foo/-/foo-1.1.0.tgz"), "shasum": "bb" } },
        }
    })
}

#[tokio::test]
async fn packument_and_disttags_are_filtered() {
    let mut upstream = mockito::Server::new_async().await;
    let up = upstream.url();
    upstream
        .mock("GET", "/foo")
        .with_status(200)
        .with_body(packument(&up).to_string())
        .create_async()
        .await;

    let tmp = TempDir::new().unwrap();
    let osv = TempDir::new().unwrap();
    write_osv(osv.path());
    let app = router(config_for(&up, tmp.path().to_path_buf(), osv.path().to_path_buf()));

    // packument: 1.0.0 removed, 1.1.0 kept.
    let resp = app.clone().oneshot(Request::get("/foo").body(Body::empty()).unwrap()).await.unwrap();
    assert_eq!(resp.status(), StatusCode::OK);
    let body: Value = serde_json::from_slice(&body_bytes(resp.into_body()).await).unwrap();
    assert!(body["versions"].get("1.0.0").is_none(), "vulnerable version present");
    assert!(body["versions"].get("1.1.0").is_some());
    assert!(body["time"].get("1.0.0").is_none(), "time entry present");
    assert!(body["time"].get("1.1.0").is_some());
    assert!(body["dist-tags"].get("latest").is_none(), "latest tag not removed");
    assert_eq!(body["dist-tags"]["safe"], "1.1.0");

    // second request (cache) is identically filtered.
    let resp2 = app.clone().oneshot(Request::get("/foo").body(Body::empty()).unwrap()).await.unwrap();
    let body2: Value = serde_json::from_slice(&body_bytes(resp2.into_body()).await).unwrap();
    assert!(body2["versions"].get("1.0.0").is_none());

    // version manifest for removed version -> 404
    let m = app.clone().oneshot(Request::get("/foo/1.0.0").body(Body::empty()).unwrap()).await.unwrap();
    assert_eq!(m.status(), StatusCode::NOT_FOUND);
    let ok = app.clone().oneshot(Request::get("/foo/1.1.0").body(Body::empty()).unwrap()).await.unwrap();
    assert_eq!(ok.status(), StatusCode::OK);

    // dist-tags endpoint
    let dt = app.clone().oneshot(Request::get("/-/package/foo/dist-tags").body(Body::empty()).unwrap()).await.unwrap();
    let dtb: Value = serde_json::from_slice(&body_bytes(dt.into_body()).await).unwrap();
    assert!(dtb.get("latest").is_none());
    assert_eq!(dtb["safe"], "1.1.0");
}

#[tokio::test]
async fn vulnerable_tarball_is_403_without_upstream() {
    let mut upstream = mockito::Server::new_async().await;
    let up = upstream.url();
    // No mock registered for the tarball -> if upstream is hit, mockito 501s.
    let tmp = TempDir::new().unwrap();
    let osv = TempDir::new().unwrap();
    write_osv(osv.path());
    let app = router(config_for(&up, tmp.path().to_path_buf(), osv.path().to_path_buf()));

    let resp = app.oneshot(Request::get("/foo/-/foo-1.0.0.tgz").body(Body::empty()).unwrap()).await.unwrap();
    assert_eq!(resp.status(), StatusCode::FORBIDDEN);
    let body = String::from_utf8(body_bytes(resp.into_body()).await).unwrap();
    assert!(body.contains("GHSA-foo-bar"), "advisory id missing from body: {body}");
}

#[tokio::test]
async fn scoped_tarball_canonicalized() {
    let mut upstream = mockito::Server::new_async().await;
    let up = upstream.url();
    let m = upstream
        .mock("GET", "/@types/node/-/node-20.0.0.tgz")
        .with_status(200)
        .with_body("TARBALL")
        .expect(1)
        .create_async()
        .await;
    let tmp = TempDir::new().unwrap();
    let osv = TempDir::new().unwrap();
    write_osv(osv.path());
    let app = router(config_for(&up, tmp.path().to_path_buf(), osv.path().to_path_buf()));

    let enc = app.clone().oneshot(Request::get("/@types/node/-/%40types%2Fnode-20.0.0.tgz").body(Body::empty()).unwrap()).await.unwrap();
    assert_eq!(enc.status(), StatusCode::OK);
    assert_eq!(body_bytes(enc.into_body()).await, b"TARBALL");

    let canon = app.clone().oneshot(Request::get("/@types/node/-/node-20.0.0.tgz").body(Body::empty()).unwrap()).await.unwrap();
    assert_eq!(canon.status(), StatusCode::OK);
    assert_eq!(body_bytes(canon.into_body()).await, b"TARBALL");

    m.assert_async().await; // upstream hit exactly once
    assert!(tmp.path().join(".pnpr-cache/@types/node/node-20.0.0.tgz").exists(), "canonical cache path missing");
}
